# test_inventory.py
import unittest
from inventory import add_item, remove_item, total_value

class TestInventory(unittest.TestCase):

    def test_add_item(self):
        inventory = {}
        inventory = add_item(inventory, "apple", 5)
        self.assertEqual(inventory["apple"], 5)
        inventory = add_item(inventory, "banana", 3)
        self.assertEqual(inventory["banana"], 3)
        inventory = add_item(inventory, "apple", 2)
        self.assertEqual(inventory["apple"], 7)

    def test_remove_item(self):
        inventory = {"apple": 10}
        inventory = remove_item(inventory, "apple", 3)
        self.assertEqual(inventory["apple"], 7)
        inventory = remove_item(inventory, "apple", 7)
        self.assertEqual(inventory["apple"], 0)
        inventory = remove_item(inventory, "apple", 1) # Should not raise error
        self.assertEqual(inventory["apple"], 0)

        inventory = remove_item(inventory, "orange", 2)  # Should not raise KeyError
        self.assertEqual(inventory, {})

    def test_total_value(self):
        prices = {"apple": 1.0, "banana": 0.5}
        inventory = {"apple": 5, "banana": 3}
        self.assertAlmostEqual(total_value(inventory, prices), 5.5)
        inventory = {"apple": 5, "banana": 3, "orange": 2}
        self.assertAlmostEqual(total_value(inventory, prices), 6.5)
        prices = {}
        self.assertAlmostEqual(total_value(inventory, prices), 0.0)

if __name__ == '__main__':
    unittest.main()
```

